@sig trait EnergyEvidenceAssessor_Api {
  def id: Art.BridgeId
  def energy_evidence_Id : Art.PortId
  def energy_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var energy_assessment: Observation_Sortie_Eligibility_Supervisor.EnergyAssessment = $

  def put_energy_assessment(value : Observation_Sortie_Eligibility_Supervisor.EnergyAssessment) : Unit = {
    Contract(
      Modifies(energy_assessment),
      Ensures(
        energy_assessment == value
      )
    )
    Spec {
      energy_assessment = value
    }

    Art.putValue(energy_assessment_Id, Observation_Sortie_Eligibility_Supervisor.EnergyAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class EnergyEvidenceAssessor_Initialization_Api (
  val id: Art.BridgeId,
  val energy_evidence_Id : Art.PortId,
  val energy_assessment_Id : Art.PortId) extends EnergyEvidenceAssessor_Api

@datatype class EnergyEvidenceAssessor_Operational_Api (
  val id: Art.BridgeId,
  val energy_evidence_Id : Art.PortId,
  val energy_assessment_Id : Art.PortId) extends EnergyEvidenceAssessor_Api {

  // Logika spec var representing port state for incoming data port
  @spec var energy_evidence: Observation_Sortie_Eligibility_Supervisor.EnergyEvidence = $

  def get_energy_evidence() : Option[Observation_Sortie_Eligibility_Supervisor.EnergyEvidence] = {
    Contract(
      Ensures(
        Res == Some(energy_evidence)
      )
    )
    val value : Option[Observation_Sortie_Eligibility_Supervisor.EnergyEvidence] = Art.getValue(energy_evidence_Id) match {
      case Some(Observation_Sortie_Eligibility_Supervisor.EnergyEvidence_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port energy_evidence.  Expecting 'Observation_Sortie_Eligibility_Supervisor.EnergyEvidence_Payload' but received ${v}")
        None[Observation_Sortie_Eligibility_Supervisor.EnergyEvidence]()
      case _ => None[Observation_Sortie_Eligibility_Supervisor.EnergyEvidence]()
    }
    return value
  }
}
